from pathlib import Path
import json,hashlib,zipfile
ROOT=Path(__file__).resolve().parents[1]
read=lambda p:json.loads(p.read_text(encoding='utf-8'))
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
v=read(ROOT/'reports/review_verification.json');assert v['passed'] and v['revision'].endswith('E04')
req=read(ROOT/'source/requirements.json');req['revision']='E04 visual review';req['current_geometry']='source/armor_E04.json';req['owner_visual_approval']='Pending';req['old_model_preservation_verified']=True
(ROOT/'source/requirements.json').write_text(json.dumps(req,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
p=ROOT/'README.md';s=p.read_text(encoding='utf-8').replace('E03','E04').replace('на37','на39')
s=s.replace('E04 уточнил высоту пояса, длину пальто и расположение символов.','E03 уточнил высоту пояса, длину пальто и расположение символов. E04 расширил передний разрез, добавил ремни на брюках и доработал крепления капюшона.')
s=s.replace('`refine_E02.py` и `refine_E04.py`','`refine_E02.py`, `refine_E03.py` и `refine_E04.py`')
p.write_text(s,encoding='utf-8')
html='''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>EREZ — Разломный инженер / E04</title><style>body{margin:24px auto;padding:0 20px;max-width:1440px;background:#1b1d22;color:#dce4e3;font:17px/1.6 system-ui}h1{font-size:34px}p{max-width:1000px}a{color:#8bd3ce}img{max-width:100%;display:block;border-radius:12px}button{padding:10px 20px;background:#394245;color:#e4eeed;border:1px solid #667674;border-radius:8px;margin-right:8px;cursor:pointer}.stage{position:relative;aspect-ratio:3/2;background:#777;border-radius:12px;overflow:hidden}.stage img{position:absolute;width:100%;height:100%;object-fit:contain}.stage #current{opacity:1}label{display:flex;gap:15px;align-items:center;margin:15px 0}input{width:min(550px,65%)}.views{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.note{padding:18px;background:#293137;border-left:4px solid #5fa49e}small{color:#b5c0bf}@media(max-width:700px){.views{grid-template-columns:1fr}}</style><h1>EREZ / Разломный инженер / E04</h1><p>Визуальная версия брони на основе сохранённого S03. Цель этого этапа — приблизить внешность к предоставленному референсу. Модель действительно построена и отрендерена в Blender; это ещё не игровая броня.</p><button onclick="set(0)">Референс</button><button onclick="set(100)">Текущая модель E04</button><label>Сопоставление <input id="mix" type="range" min="0" max="100" value="100" oninput="set(this.value)"><span id="value">E04:100%</span></label><div class="stage"><img src="../source/reference/owner_reference.jpg" alt="Референс владельца"><img id="current" src="../preview/engineer_E04_front_back.png" alt="Реальный рендер E04"></div><p><a href="../assembly/EREZ_Rift_Engineer_Armor_E04.blend">Открыть сцену Blender</a> · <a href="../exports/EREZ_Rift_Engineer_Armor_E04.glb">Модель GLB</a> · <a href="../exports/EREZ_Rift_Engineer_Armor_E04_review.zip">Все материалы</a></p><h2>Отдельные ракурсы</h2><div class="views"><a href="../preview/engineer_E04_front.png"><img src="../preview/engineer_E04_front.png" alt="Спереди"></a><a href="../preview/engineer_E04_back.png"><img src="../preview/engineer_E04_back.png" alt="Сзади"></a><a href="../preview/engineer_E04_quarter.png"><img src="../preview/engineer_E04_quarter.png" alt="Три четверти"></a></div><h2>Где старая модель</h2><p>S03 сохранён без изменения. Новая версия переносит или уточняет39 его деталей, использует прежние точки крепления и исходную ткань. Здесь его прежний рендер:</p><img style="max-width:600px" src="../source/reference/previous_S03_blender.png" alt="Сохранённый прежний S03"><p>Главные доработки: объёмная респираторная маска, узкий визор, воротник, ремень с фурнитурой, сформованные подсумки, раздельные расходящиеся полы пальто, вертикальный прибор, ремни на брюках. Маген-Давид и ארז — настоящая геометрия.</p><div class="note">Форма и цвет нуждаются в визуальной приёмке владельца. Перенос в Minecraft, движения, вид от первого лица, рюкзаки, элитры и производительность ещё не проверены. Характеристики, рецепты и способности не добавлялись.</div><p><a href="review_verification.json">Проверка геометрии и файлов</a> · <a href="../README.md">Исходники и воспроизведение</a></p><small>CPM, скин, аккаунт, сервер, каталог лаунчера и рабочий профиль не менялись.</small><script>function set(v){document.getElementById('current').style.opacity=v/100;document.getElementById('mix').value=v;document.getElementById('value').textContent='E04:'+v+'%'}</script></html>'''
(ROOT/'reports/review.html').write_text(html,encoding='utf-8')
out=ROOT/'exports/EREZ_Rift_Engineer_Armor_E04_review.zip'
with zipfile.ZipFile(out,'w',zipfile.ZIP_DEFLATED) as z:
    files=[ROOT/'README.md',ROOT/'source/requirements.json',ROOT/'source/armor_E04.json',ROOT/'source/armor_E04_parameters.json',ROOT/'source/armor_E04_atlas.png',ROOT/'assembly/EREZ_Rift_Engineer_Armor_E04.blend',ROOT/'exports/EREZ_Rift_Engineer_Armor_E04.glb',ROOT/'reports/review.html',ROOT/'reports/review_verification.json',ROOT/'reports/blender.json']
    files+=list((ROOT/'source/reference').glob('*'))+list((ROOT/'source').glob('palette_*.png'))+list((ROOT/'preview').glob('*E04*.png'))+list((ROOT/'tools').glob('*.py'))
    for f in files:
        if f.is_file():z.write(f,f.relative_to(ROOT))
(ROOT/'reports/package.json').write_text(json.dumps({'path':str(out),'sha256':sha(out),'bytes':out.stat().st_size,'stage':'Visual candidate; owner review pending'},indent=2)+'\n',encoding='utf-8')
print(json.dumps({'archive_bytes':out.stat().st_size,'source_sha256':v['authoritative_mesh_sha256'],'parts':v['parts'],'faces':v['faces'],'game_implemented':False}))
